  mounted() {
    this.challenge_reroll();
  },
  watch: {
    nextmission(newVal) {
      this.start(newVal);
    },
  },
  components: {},
  methods: {
    targetselect() {
      let list = [];
      list = list.concat(this.$missions.Main);
      list = list.concat(this.$missions.DLC1);
      list = list.concat(this.$missions.DLC2);
      this.target = list;
    },
    start(num) {
      this.transitionStart();
      setTimeout(this.next, 600, num);
    },
    challenge_reroll() {
      let arr = [];
      let numArr = [];
      let challengenum = 0;
      this.surinuke_text = "";
      for (var i = 0; i < this.challenge_list.length; i++) {
        if (this.challenge_list[i].available) {
          if (
            this.target[this.currentmission].status == 0 ||
            this.target[this.currentmission].status == 4
          ) {
            arr.unshift(this.challenge_list[i]);
            challengenum = challengenum + 1;
          } else {
            if (!(this.challenge_list[i].cat == 2)) {
              arr.unshift(this.challenge_list[i]);
              challengenum = challengenum + 1;
            }
          }
        }
      }

      if (this.currentmission >= 46) {
        this.result_challenge_val = 3;
      } else if (this.currentmission >= 13) {
        this.result_challenge_val = 2;
      } else {
        this.result_challenge_val = 1;
      }

      for (var j = 0, len = arr.length; j < this.result_challenge_val; ) {
        let rndNum = Math.floor(Math.random() * len);
        if (arr[rndNum].cat == 4) {
          this.surinuke_text = "";
          console.log("cat4抽選");
          if (Math.random() < 0.5) {
            numArr = [arr[rndNum]];
            console.log("cat4あたり");
            this.surinuke_text = "高危険度！がんばりましょう";
            break;
          } else {
            arr[rndNum] = arr[len - 1];
            this.surinuke_text = "どうやら許されたようだ…";
            console.log("すりぬけ！");
          }
        } else {
          numArr.push(arr[rndNum]);
          arr[rndNum] = arr[len - 1];
          j++, len--;
        }
      }

      this.result_challenge = numArr;
      console.log(this.result_challenge);
    },
    next(num) {
      if (num == "next") {
        num = this.currentmission + 1;
      } else if (num == "prev") {
        num = this.currentmission - 1;
      }
      if (num < 0) {
        this.currentmission = 0;
      } else if (num >= this.target.length - 1) {
        this.currentmission = this.target.length - 1;
      } else {
        this.currentmission = num;
      }
      this.challenge_reroll();
      setTimeout(this.transitionEnd, 200);
    },
    transitionStart() {
      let elm = document.getElementsByClassName("transition");
      for (var i = 0; i < elm.length; i++) {
        elm[i].classList.add("nowloading");
      }
    },
    transitionEnd() {
      let elm = document.getElementsByClassName("transition");
      for (var i = 0; i < elm.length; i++) {
        elm[i].classList.remove("nowloading");
      }
    },
  },
};
